package com.example

/**
 * High-quality, 100% curriculum-accurate Question Bank for Sinhala Language & Literature (සිංහල)
 * Covers 10 distinct syllabus lessons with 10 unique MCQs per set (100 total distinct questions).
 */
object QuizBankSinhala {

  fun getQuestion(
    grade: String,
    setIdx: Int,
    qIdx: Int,
    qNumber: Int,
    topic: String
  ): QuizQuestion {
    return when (setIdx) {
      // SET 1: සිංහල අක්ෂර මාලාව හා අක්ෂර වින්‍යාසය
      1 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "ශුද්ධ සිංහල හෝඩියේ අඩංගු මුළු අක්ෂර සංඛ්‍යාව කොපමණද?", listOf("අක්ෂර 32 කි (ස්වර 8, ව්‍යංජන 24)", "අක්ෂර 54 කි", "අක්ෂර 60 කි", "අක්ෂර 48 කි"), 0, "සිදත් සඟරාවට අනුව ශුද්ධ සිංහල හෝඩියේ අක්ෂර 32ක් ඇත.")
        2 -> QuizQuestion(qNumber, "නූතන සම්මත සිංහල හෝඩියේ (මිශ්‍ර සිංහල හෝඩියේ) ඇති මුළු අක්ෂර සංඛ්‍යාව කීයද?", listOf("අක්ෂර 60 කි (ස්වර 18, ව්‍යංජන 42)", "අක්ෂර 50 කි", "අක්ෂර 32 කි", "අක්ෂර 64 කි"), 0, "ජාතික අධ්‍යාපන ආයතනය සම්මත කර ඇති නූතන සිංහල හෝඩියේ අක්ෂර 60ක් අඩංගු වේ.")
        3 -> QuizQuestion(qNumber, "නිරවද්‍ය අක්ෂර වින්‍යාසය සහිත පදය තෝරන්න.", listOf("ප්‍රවීන", "ප්‍රවීණ", "ප්‍රවින", "ප්‍රවිණ"), 1, "කෘදන්ත හෝ තත්සම පදවල 'ර' කාරයට පසු මූර්ධජ 'ණ' යෙදේ (ප්‍රවීණ).")
        4 -> QuizQuestion(qNumber, "මූර්ධජ 'ළ' අක්ෂරය නිවැරදිව යෙදී ඇති පදය කුමක්ද?", listOf("පිලිතුර", "පිළිතුර", "පිලීතුර", "පිලිතූර"), 1, "'පිළිතුර', 'කළිසම', 'කළුවර' ආදී පදවල මූර්ධජ 'ළ' නිවැරදිව යෙදේ.")
        5 -> QuizQuestion(qNumber, "සිංහල හෝඩියේ ඇති නාසික්‍ය (නාසයෙන් උච්චාරණය වන) අනුනාසික අක්ෂර 5 මොනවාද?", listOf("ඞ, ඤ, ණ, න, ම", "ක, ච, ට, ත, ප", "ග, ජ, ඩ, ද, බ", "ය, ර, ල, ව, ස"), 0, "පංචම අක්ෂර වන ඞ, ඤ, ණ, න, ම අනුනාසික අක්ෂර වේ.")
        6 -> QuizQuestion(qNumber, "අඩක් උච්චාරණය වන 'සඤ්ඤක' (අර්ධ නාසික්‍ය) අක්ෂර 5 කුමක්ද?", listOf("ඟ, ඦ, ඬ, ඳ, ඹ", "ක, ග, ච, ජ, ට", "අ, ආ, ඇ, ඈ, ඉ", "ය, ර, ල, ව, ශ"), 0, "සිංහල භාෂාවට පමණක් අනන්‍ය වූ අර්ධ නාසික්‍ය අක්ෂර 5 සඤ්ඤක අක්ෂර වේ.")
        7 -> QuizQuestion(qNumber, "තාලුජ 'ශ' සහ මූර්ධජ 'ෂ' අක්ෂර නිවැරදිව යෙදුණු පදය කුමක්ද?", listOf("විශේෂ", "විශේශ", "විෂේශ", "විසේස"), 0, "'විශේෂ' පදයේ මුලින් තාලුජ 'ශ' ද, පසුව මූර්ධජ 'ෂ' ද යෙදේ.")
        8 -> QuizQuestion(qNumber, "පහත පද අතුරින් නිවැරදි අක්ෂර වින්‍යාසය සහිත පදය තෝරන්න.", listOf("කාරුණික", "කාරුනික", "කරුනික", "කාරුණීක"), 0, "කරුණාවෙන් යුත් තැනැත්තා 'කාරුණික' වේ (මූර්ධජ ණ).")
        9 -> QuizQuestion(qNumber, "දන්තජ 'න' සහ මූර්ධජ 'ණ' භේදය වැදගත් වන 'වනය' සහ 'වණය' හි අර්ථ වෙනස කුමක්ද?", listOf("වනය = කැලය, වණය = තුවාලය", "වනය = ජලය, වණය = ගින්න", "වනය = ලේ, වණය = ඇස", "දෙකම එක සමානයි"), 0, "දන්තජ 'න' යෙදූ විට කැලය (වනය) වන අතර මූර්ධජ 'ණ' යෙදූ විට තුවාලය (වණය) වේ.")
        else -> QuizQuestion(qNumber, "ස්වයංසිද්ධව උච්චාරණය කළ හැකි අක්ෂර හඳුන්වන්නේ කුමක්ද?", listOf("ප්‍රාණාක්ෂර (ස්වර)", "ගාත්‍රාක්ෂර (ව්‍යංජන)", "සඤ්ඤක", "අයෝගවාහ"), 0, "අන් අකුරක උපකාරයක් නැතිව තනිව උච්චාරණය වන අක්ෂර ස්වර හෙවත් ප්‍රාණාක්ෂර වේ.")
      }

      // SET 2: නාම පද හා ක්‍රියා පද වර්ගීකරණය
      2 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "යම් පුද්ගලයෙකු, ස්ථානයක් හෝ වස්තුවක් හැඳින්වීමට යොදන පද වර්ගය කුමක්ද?", listOf("නාම පද (Nouns)", "ක්‍රියා පද", "නිපාත පද", "උපසර්ග පද"), 0, "නාම පද මඟින් සත්ව, පුද්ගල, ස්ථාන, ද්‍රව්‍ය හා ගුණ නාම හඳුන්වයි.")
        2 -> QuizQuestion(qNumber, "කර්මයක් අවශ්‍ය වන (කර්මකාරකයක් සහිත) ක්‍රියා පද හඳුන්වන්නේ කුමක්ද?", listOf("සකර්මක ක්‍රියා (Transitive Verbs)", "අකර්මක ක්‍රියා", "ප්‍රයෝජ්‍ය ක්‍රියා", "මිශ්‍ර ක්‍රියා"), 0, "'මම පොතක් කියවමි' හි 'කියවමි' යන්න කුමක් කියවන්නේදැයි කර්මයක් ඉල්ලන බැවින් සකර්මක වේ.")
        3 -> QuizQuestion(qNumber, "කර්මයක් අවශ්‍ය නොවන (තනිව අර්ථවත් වන) ක්‍රියා පද වර්ගය කුමක්ද?", listOf("අකර්මක ක්‍රියා (Intransitive Verbs)", "සකර්මක ක්‍රියා", "විධි ක්‍රියා", "ආශීර්වාද ක්‍රියා"), 0, "'ළමයා නිදයි', 'හිරු පායයි' ආදී ක්‍රියා සඳහා කර්මයක් අවශ්‍ය නොවේ.")
        4 -> QuizQuestion(qNumber, "අනුන් ලවා යමක් කරවීමේ අර්ථය දෙන ක්‍රියා පද වර්ගය කුමක්ද?", listOf("ප්‍රයෝජ්‍ය ක්‍රියා (Causative Verbs)", "අකර්මක ක්‍රියා", "කර්ම කාරක", "අසම්භාව්‍ය"), 0, "'ලියවයි', 'කරවයි', 'පොවයි', 'නටවයි' ආදිය ප්‍රයෝජ්‍ය ක්‍රියා වේ.")
        5 -> QuizQuestion(qNumber, "'ළමයා පාඩම් කරමින් තේ බොයි' වාක්‍යයේ 'කරමින්' යනු කුමන ක්‍රියා පදයක්ද?", listOf("මිශ්‍ර ක්‍රියාවක් (Participle)", "අවසන් ක්‍රියාවක්", "ප්‍රයෝජ්‍ය ක්‍රියාවක්", "අකර්මක ක්‍රියාවක්"), 0, "ප්‍රධාන ක්‍රියාවට සමගාමීව සිදුවන 'මින්', 'වෙමින්' සහිත පද මිශ්‍ර ක්‍රියා වේ.")
        6 -> QuizQuestion(qNumber, "'වැස්ස ලැබුණහොත් ගොවිතැන් සරු වේ' වාක්‍යයේ 'ලැබුණහොත්' යනු කුමන ක්‍රියාවක්ද?", listOf("අසම්භාව්‍ය ක්‍රියාව (Conditional Verb)", "මිශ්‍ර ක්‍රියාව", "විධි ක්‍රියාව", "පුර්ව ක්‍රියාව"), 0, "යම් කොන්දේසියක් හෝ සැකයක් දක්වන 'හොත්', 'තොත්' යෙදුණු ක්‍රියා අසම්භාව්‍ය ක්‍රියා වේ.")
